# -*- coding: utf-8 -*-
from ._helpers import intro, schema, fall, mc

KURS = dict(
    id="u07", gebiet="upc", titel="Rechtsfolgen, Zwangsgeld und Vollstreckung",
    untertitel="Unterlassung, Abhilfe, Auskunft, Schadensersatz – und wie das EPG seine Anordnungen durchsetzt",
    farbe="#c2410c", icon="rechtsfolgen",
    beschreibung="Was der Kläger nach festgestellter Verletzung bekommt: die Unterlassungsanordnung nach Art. 63 EPGÜ und ihre Reichweite (Dyson/Dreame), Abhilfemaßnahmen (Art. 64), Auskunft (Art. 67), Veröffentlichung (Art. 80) und Schadensersatz mit dem gesonderten Festsetzungsverfahren (Art. 68, R. 125 ff. VerfO). Dazu das System der Zwangsgelder nach Kodak/Fujifilm, die Pflichten des Adressaten bei Plattformen und Geoblocking (Lepu/Occlutech), der Rechtsweg gegen die Zwangsgeldfestsetzung (EOFlow/Insulet) und die Rückwirkung der Aufhebung.",
    kapitel=[
        dict(id="u07a", titel="Die Anordnungen nach Art. 63, 64, 67 und 80 EPGÜ", einheiten=[
            schema("u07a-0", "Prüfungsschema: Verletzungsklage vor dem EPG", "upc_schema_verletzungsklage",
                   "Dieser Kurs behandelt den Abschnitt C des Schemas: Wird die Verletzung festgestellt, folgen Unterlassung und Zwangsgeld (Art. 63), Abhilfe, Auskunft und Veröffentlichung (Art. 64, 67, 80), Schadensersatz (Art. 68) sowie Kosten und Vollstreckung (Art. 69, 82 EPGÜ). Alle Anordnungen stehen im Ermessen des Gerichts („kann“) und unterliegen der Verhältnismäßigkeit nach Art. 42 EPGÜ."),
            fall("u07a-1", "Nur das Angebot verboten?",
                 "Die Lokalkammer stellt fest, dass Dreame durch das **Anbieten** eines Saugroboters ein Patent von Dyson verletzt hat, und untersagt Dreame das Anbieten, Inverkehrbringen, Gebrauchen, Einführen und Besitzen der Ausführungsform. Dreame legt Berufung ein: Nachgewiesen sei nur das Angebot; die Unterlassungsanordnung müsse auf die konkret begangene Handlung beschränkt werden, da für die übrigen Benutzungsarten keine Wiederholungsgefahr bestehe.",
                 "Muss die Unterlassungsanordnung auf die konkret begangene Verletzungshandlung beschränkt werden?", False,
                 ["**Nein!** Nach Art. 63 Abs. 1 EPGÜ kann das Gericht bei festgestellter Verletzung eine Verfügung erlassen, durch die die **Fortsetzung der Verletzung** untersagt wird. Weder Art. 63 noch Art. 62 Abs. 1 oder Art. 25 lit. a EPGÜ lassen sich entnehmen, dass die Anordnung auf die bereits begangene Benutzungsart begrenzt sein müsste. Die Benutzungshandlungen des Art. 25 EPGÜ sind zwar selbständig, gehören aber zu demselben Ausschließlichkeitsrecht.",
                  "Wer eine Verletzungshandlung begangen hat, begründet in der Regel die Gefahr, dass er die Verletzung auch durch andere, bisher nicht begangene Benutzungshandlungen fortsetzt: Wer anbietet, wird liefern und in Verkehr bringen. Das Berufungsgericht hat die weite Fassung deshalb bestätigt (EPG-BerG Dyson/Dreame). Grenze bleibt die Verhältnismäßigkeit (Art. 42 EPGÜ): Das Verbot muss sich auf die verletzende Ausführungsform und die zu erwartenden Handlungen beziehen, nicht auf beliebige andere Produkte."],
                 merke="Wer einmal verletzt hat, dem droht das Verbot aller Benutzungsarten des Art. 25 EPGÜ – nicht nur der nachgewiesenen.",
                 level=2, concepts=["upc_unterlassungsanordnung", "upc_unmittelbare_verletzung"], norms=["Art. 63 Abs. 1 EPGÜ", "Art. 25 EPGÜ", "Art. 42 EPGÜ"],
                 cases=["upc_coa_dyson_dreame_auslegung"], step="step:upc_schema_verletzungsklage.3.1"),
            mc("u07a-2", "Ermessen, Mittelspersonen, Verhältnismäßigkeit",
                "Welche Aussage zur Unterlassungsanordnung nach Art. 63 EPGÜ trifft zu?",
                ["Die Unterlassungsanordnung ergeht bei festgestellter Verletzung zwingend; ein Ermessen des Gerichts besteht nicht.",
                 "Das Gericht kann die Verfügung auch gegen eine Mittelsperson erlassen, deren Dienste ein Dritter zur Patentverletzung in Anspruch nimmt, ohne dass die Mittelsperson selbst Verletzer sein muss.",
                 "Ein Geschäftsführer haftet allein wegen seiner Organstellung stets als Mittäter der von seiner Gesellschaft begangenen Verletzung.",
                 "Zwangsgelder nach Art. 63 Abs. 2 EPGÜ sind an den Kläger zu zahlen und ersetzen dessen Schaden."],
                1,
                ["**Richtig ist die zweite Aussage.** Art. 63 Abs. 1 Satz 2 EPGÜ erlaubt eine Verfügung gegen **Mittelspersonen**, deren Dienste von einem Dritten zwecks Verletzung in Anspruch genommen werden – die Umsetzung von Art. 11 Satz 3 DurchsetzungsRL. Eigene Verletzerhaftung der Mittelsperson ist nicht erforderlich; die Anordnung schließt die Lücke, wenn der Verletzer selbst schwer zu fassen ist.",
                 "Die erste Aussage verkennt das Ermessen: Art. 63 Abs. 1 sagt „kann“; das Gericht prüft die Verhältnismäßigkeit nach Art. 42 EPGÜ, übt das Ermessen aber regelmäßig zugunsten des Verbots aus. Die dritte Aussage ist falsch: Die bloße Organstellung macht den Geschäftsführer nicht zum Mittäter; er haftet nur, wenn er das Unternehmen zweckgerichtet zur Verletzung nutzt oder trotz Kenntnis und Zumutbarkeit nicht einschreitet (EPG-BerG Belkin/Philips). Die vierte Aussage ist falsch: Zwangsgelder fließen nach Art. 63 Abs. 2 und Art. 82 Abs. 4 EPGÜ **an das Gericht** und lassen den Schadensersatzanspruch unberührt."],
                merke="Art. 63: Ermessen, Verhältnismäßigkeit, Mittelspersonen – und das Zwangsgeld geht an das Gericht, nicht an den Kläger.",
                level=2, concepts=["upc_unterlassungsanordnung", "upc_verletzer"], norms=["Art. 63 Abs. 1 EPGÜ", "Art. 63 Abs. 2 EPGÜ", "Art. 42 EPGÜ", "Art. 11 DurchsetzungsRL"],
                cases=["upc_coa_belkin_philips_anbieten"], step="step:upc_schema_verletzungsklage.3.1"),
            fall("u07a-3", "Umbau statt Vernichtung",
                 "Die Lokalkammer stellt fest, dass die Filteranlagen der Beklagten Ventra das Patent der Klägerin Aquilon verletzen. Aquilon beantragt, die noch bei Ventra lagernden 400 Anlagen zu vernichten. Ventra legt ein Gutachten vor, wonach sich das patentverletzende Ventilmodul mit geringem Aufwand gegen ein nicht verletzendes Modul austauschen lässt, und erklärt sich dazu bereit. Aquilon meint, bei festgestellter Verletzung sei die Vernichtung zwingend anzuordnen.",
                 "Muss das Gericht die Vernichtung anordnen?", False,
                 ["**Nein!** Art. 64 Abs. 1 EPGÜ stellt die Abhilfemaßnahmen in das Ermessen des Gerichts („kann“); Abs. 2 nennt neben der Vernichtung (lit. e) gleichrangig die **Beseitigung der verletzenden Eigenschaft** (lit. c), den Rückruf (lit. b) und die endgültige Entfernung aus den Vertriebswegen (lit. d). Nach Abs. 4 berücksichtigt das Gericht die Verhältnismäßigkeit zwischen der Schwere der Verletzung und der Maßnahme, die **Bereitschaft des Verletzers, das Material in einen nichtverletzenden Zustand zu versetzen**, sowie die Interessen Dritter.",
                  "Ventra hat genau diese Bereitschaft dargelegt und belegt, dass der Austausch des Moduls die Verletzung beseitigt. Die Vernichtung wäre dann das schärfere Mittel ohne zusätzlichen Nutzen für Aquilon. Das Gericht wird die Beseitigung der verletzenden Eigenschaft anordnen, auf Kosten von Ventra (Abs. 3), und den Vollzug im Tenor konkretisieren (R. 118 VerfO). Die Vorschrift setzt Art. 10 DurchsetzungsRL um und entspricht § 140a PatG und § 18 MarkenG, wo die Unverhältnismäßigkeit ebenfalls den Vernichtungsanspruch ausschließt."],
                 merke="Art. 64 Abs. 4: Vernichtung nur, wenn Umbau, Rückruf oder Entfernung nicht genügen – die Bereitschaft des Verletzers zählt.",
                 level=2, concepts=["upc_abhilfemassnahmen", "upc_verfahrensgrundsaetze"], norms=["Art. 64 Abs. 2 EPGÜ", "Art. 64 Abs. 4 EPGÜ", "Art. 42 EPGÜ", "R. 118 VerfO"],
                 step="step:upc_schema_verletzungsklage.3.2"),
            fall("u07a-4", "Auskunft vom Spediteur",
                 "Nach der Verurteilung der Herstellerin Corvid beantragt die Patentinhaberin Meridian eine Auskunftsanordnung auch gegen die Spedition Lorentz, die die verletzenden Pumpen nachweislich in gewerblichem Umfang für Corvid eingelagert und an Händler in Deutschland, Frankreich und Italien ausgeliefert hat. Lorentz wendet ein, sie sei keine Verletzerin und nicht Partei des Verletzungsverfahrens; Art. 67 EPGÜ richte sich nur gegen den Verletzer.",
                 "Kann das Gericht Lorentz zur Auskunft über Mengen und Empfänger verpflichten?", True,
                 ["**Ja!** Art. 67 Abs. 1 EPGÜ richtet sich an den Verletzer; Abs. 2 erstreckt die Auskunftspflicht auf **jede dritte Partei**, die nachweislich verletzende Erzeugnisse in gewerblichem Ausmaß in ihrem Besitz hatte (lit. a) oder für verletzende Tätigkeiten genutzte Dienstleistungen in gewerblichem Ausmaß erbracht hat (lit. b). Eine Spedition, die die Ware einlagert und ausliefert, erfüllt beide Alternativen.",
                  "Der Antrag muss begründet sein und die Verhältnismäßigkeit wahren (Abs. 1); Gegenstand sind Ursprung und Vertriebswege, Mengen und Preise sowie die Identität der beteiligten Dritten (Abs. 1 lit. a bis c). Die Auskunft bereitet das Schadensersatzverfahren nach R. 125 ff. VerfO vor und ist als Anordnung nach Art. 67 EPGÜ mit der Berufung binnen 15 Tagen anfechtbar (Art. 73 Abs. 2 lit. a EPGÜ). Die Vorschrift setzt Art. 8 DurchsetzungsRL um; im deutschen Recht entspricht ihr die Drittauskunft nach § 140b Abs. 2 PatG und § 19 Abs. 2 MarkenG."],
                 merke="Art. 67 Abs. 2: Auskunft auch vom Nichtverletzer, der gewerblich besessen, geliefert oder Dienste erbracht hat.",
                 level=2, concepts=["upc_auskunft", "upc_beweisanordnung"], norms=["Art. 67 Abs. 1 EPGÜ", "Art. 67 Abs. 2 EPGÜ", "R. 191 VerfO", "Art. 8 DurchsetzungsRL"],
                 step="step:upc_schema_verletzungsklage.3.2"),
        ]),
        dict(id="u07b", titel="Schadensersatz (Art. 68 EPGÜ) und das Festsetzungsverfahren", einheiten=[
            intro("u07b-0", "Zwei Stufen: Grund im Urteil, Höhe im gesonderten Verfahren",
                  "Art. 68 Abs. 1 EPGÜ verpflichtet den Verletzer, der **wusste oder vernünftigerweise hätte wissen müssen**, dass er eine Verletzung begeht, zu angemessenem Schadensersatz. Ziel ist der Ausgleich des tatsächlichen Schadens: Die geschädigte Partei ist so zu stellen, wie sie ohne die Verletzung stünde, dem Verletzer darf kein Nutzen bleiben, ein **Strafcharakter** ist ausgeschlossen (Abs. 2). Bei der Bemessung berücksichtigt das Gericht alle Aspekte, insbesondere Gewinneinbußen des Geschädigten und Verletzergewinn, in geeigneten Fällen auch immaterielle Schäden (Abs. 3 lit. a), oder es setzt stattdessen einen **Pauschalbetrag** auf Grundlage mindestens der hypothetischen Lizenzgebühr fest (Abs. 3 lit. b). Der gutgläubige Verletzer schuldet keinen Schadensersatz, kann aber zur Herausgabe der Gewinne oder zu einer Entschädigung verpflichtet werden (Abs. 4). Das ist die Umsetzung von Art. 13 DurchsetzungsRL und entspricht der dreifachen Schadensberechnung des § 139 Abs. 2 PatG. Verfahrensrechtlich arbeitet das EPG zweistufig: In der Entscheidung in der Sache spricht das Gericht den Schadensersatz dem Grunde nach zu und kann eine vorläufige Zahlung anordnen (R. 118.1, R. 119 VerfO); die **Höhe** wird auf Antrag binnen **eines Jahres** nach Zustellung der Endentscheidung in einem gesonderten Verfahren festgesetzt (R. 125, 126 VerfO), das mit einem Antrag auf **Offenlegung der Bücher** verbunden werden kann (R. 131.1 lit. c, R. 141 ff. VerfO).",
                  concepts=["upc_schadensersatz", "upc_auskunft"], norms=["Art. 68 Abs. 1 EPGÜ", "Art. 68 Abs. 3 EPGÜ", "R. 118.1 VerfO", "R. 126 VerfO"]),
            fall("u07b-1", "Das französische Urteil und die Höhe des Schadens",
                 "Ein französisches Gericht hat 2022 festgestellt, dass REEL ein europäisches Patent von Fives verletzt hat, und REEL dem Grunde nach zum Schadensersatz verurteilt; über die Höhe wurde nicht entschieden. Das Patent ist im Zeitpunkt des Inkrafttretens des EPGÜ noch in Kraft. 2024 erhebt Fives beim EPG eine selbständige Klage auf Festsetzung des Schadensersatzes für die Verletzungshandlungen der Jahre 2019 bis 2022. REEL rügt mit Einspruch nach R. 19 VerfO die Zuständigkeit: Das EPG sei nur für Verletzungsklagen zuständig, nicht für die bloße Bezifferung eines national festgestellten Anspruchs, und schon gar nicht für Handlungen vor dem 1. Juni 2023.",
                 "Ist das EPG für die selbständige Schadensersatzklage zuständig?", True,
                 ["**Ja!** Die Zuständigkeit des EPG nach Art. 32 Abs. 1 lit. a EPGÜ für Klagen wegen tatsächlicher oder drohender Patentverletzung umfasst auch eine **selbständige Klage auf Festsetzung von Schadensersatz**, nachdem ein nationales Gericht die Verletzung und die Ersatzpflicht dem Grunde nach festgestellt hat. Der Schadensersatz nach Art. 68 EPGÜ ist eine Rechtsfolge der Verletzung; das EPGÜ trennt Grund und Höhe selbst (R. 118.1, R. 125 ff. VerfO), sodass die Höhenfestsetzung eine eigene Klage sein kann.",
                  "Die Zuständigkeit erfasst auch Verletzungshandlungen **vor dem 1. Juni 2023**, solange das Patent bei Inkrafttreten des EPGÜ noch nicht erloschen war; Art. 32 EPGÜ enthält keine zeitliche Beschränkung auf Handlungen nach dem Inkrafttreten (EPG-BerG Fives/REEL). Welches materielle Recht für die Altzeit gilt und ob ein Rückwirkungsverbot greift, ist eine Frage der Begründetheit, nicht der Zuständigkeit (EPG-BerG Knaus Tabbert). Der Einspruch nach R. 19 VerfO bleibt daher ohne Erfolg."],
                 merke="Schadensersatz ist eine eigene Klage wert: Das EPG beziffert auch, was ein nationales Gericht dem Grunde nach zugesprochen hat – für Altfälle eingeschlossen.",
                 level=3, concepts=["upc_schadensersatz", "upc_altfaelle", "upc_sachliche_zustaendigkeit"], norms=["Art. 68 EPGÜ", "Art. 32 Abs. 1 EPGÜ", "R. 125 VerfO", "R. 19 VerfO"],
                 cases=["upc_coa_fives_reel_altfaelle", "upc_coa_knaus_tabbert_altfaelle"], step="step:upc_schema_verletzungsklage.3.3"),
            mc("u07b-2", "Das Festsetzungsverfahren nach R. 125 bis 131 VerfO",
                "Was gilt für das weitere Vorgehen von Helion?",
                ["Helion muss die Höhe des Schadensersatzes binnen eines Monats nach der Entscheidung beantragen, sonst ist der Anspruch verfallen.",
                 "Helion kann binnen eines Jahres nach Zustellung der Endentscheidung die Festsetzung des Schadensersatzes beantragen und den Antrag mit einem Antrag auf Offenlegung der Bücher verbinden.",
                 "Die Höhe des Schadensersatzes kann nur im Verletzungsurteil selbst festgesetzt werden; ein Nachverfahren kennt die VerfO nicht.",
                 "Helion kann als Ersatz der Lizenzanalogie das Doppelte der üblichen Lizenzgebühr verlangen, weil Solvix die Verletzung kannte."],
                1,
                ["**Richtig ist die zweite Aussage.** Nach R. 126 VerfO muss die obsiegende Partei den Antrag auf Festsetzung des Schadensersatzes **innerhalb eines Jahres** nach Zustellung der Endentscheidung zur Verletzung und Rechtsgültigkeit (einschließlich einer Berufungsentscheidung) stellen; er kann einen Antrag auf **Offenlegung der Bücher** enthalten (R. 126, R. 131.1 lit. c, R. 141 ff. VerfO). Erst nach der Offenlegung muss Helion die geforderte Wiedergutmachung, die Berechnung und die Beweismittel angeben (R. 131.2 VerfO).",
                 "Die Monatsfrist der ersten Option gehört zur Kostenfestsetzung (R. 151 VerfO), nicht zum Schadensersatz. Die dritte Option widerspricht R. 118.1 Satz 2 und R. 125 VerfO, die die Bestimmung der Höhe im gesonderten Verfahren ausdrücklich vorsehen. Die vierte Option scheitert an Art. 68 Abs. 2 Satz 3 EPGÜ: Der Schadensersatz hat keinen Strafcharakter; die Lizenzanalogie nach Abs. 3 lit. b ist eine Pauschale auf Grundlage „mindestens“ der angemessenen Gebühr, kein Verletzerzuschlag."],
                sachverhalt="Die Lokalkammer hat die Beklagte Solvix am 3. März zur Unterlassung verurteilt und ihre Pflicht zum Schadensersatz dem Grunde nach festgestellt; die Entscheidung wurde am 10. März zugestellt, Berufung wurde nicht eingelegt. Die Klägerin Helion will nun den Betrag beziffert haben, kennt aber weder Stückzahlen noch Preise von Solvix.",
                merke="Ein Jahr für den Schadensersatz (R. 126), ein Monat für die Kosten (R. 151) – und die Bücher öffnet R. 141.",
                level=2, concepts=["upc_schadensersatz"], norms=["R. 125 VerfO", "R. 126 VerfO", "R. 131 VerfO", "Art. 68 Abs. 2 EPGÜ"],
                step="step:upc_schema_verletzungsklage.3.3"),
        ]),
        dict(id="u07c", titel="Vollstreckung und Zwangsgeld (Art. 82 EPGÜ, R. 354 VerfO)", einheiten=[
            intro("u07c-0", "Wie das EPG vollstreckt: Vollstreckungsstaat, Zwangsgeld, Rückwirkung",
                  "Entscheidungen und Anordnungen des EPG sind in **allen Vertragsmitgliedstaaten** vollstreckbar; das Vollstreckungsverfahren richtet sich nach dem Recht des Vollstreckungsstaats (Art. 82 Abs. 1, 3 EPGÜ). Sie sind ab Zustellung unmittelbar vollstreckbar (R. 354.1 VerfO), das Gericht kann die Vollstreckung aber von einer Sicherheitsleistung abhängig machen (Art. 82 Abs. 2 EPGÜ, R. 352 VerfO). Zwei Hürden stehen vor der Vollstreckung einer Sachentscheidung: Der Kläger muss dem Gericht mitteilen, **welchen Teil** der Anordnungen er vollstrecken will (Notice of intention to enforce), und gegebenenfalls eine beglaubigte Übersetzung in die Amtssprache des Vollstreckungsstaats vorlegen; erst mit Zustellung dieser Mitteilung an den Beklagten wird die Anordnung gegen ihn vollstreckbar (R. 118.8 VerfO). Das eigentliche Druckmittel des EPG ist das **Zwangsgeld**: Anordnungen können für den Fall der Zuwiderhandlung wiederholte, an das Gericht zahlbare Zwangsgeldzahlungen vorsehen (R. 354.3 VerfO, Art. 82 Abs. 4 EPGÜ); bei behaupteter Zuwiderhandlung setzt der erstinstanzliche Spruchkörper auf Antrag oder von Amts wegen das Zwangsgeld fest (R. 354.4 VerfO), nach Anhörung beider Parteien im Verfahren der R. 264 VerfO. Das Berufungsgericht hat das System in Kodak/Fujifilm geordnet: Androhung im Urteil oder nachträglich, Bestimmung nach Zeitraum, Stück oder Handlung, abschreckend aber verhältnismäßig. Wird die vollstreckte Anordnung später aufgehoben, wirkt das zurück (Art. 75 Abs. 1 EPGÜ) – und der Vollstreckungsschuldner kann Ersatz des Vollstreckungsschadens verlangen (R. 354.2 VerfO).",
                  concepts=["upc_vollstreckung", "upc_zwangsgeld"], norms=["Art. 82 EPGÜ", "R. 354 VerfO", "R. 118.8 VerfO", "R. 352 VerfO"],
                  cases=["upc_coa_kodak_fujifilm_zwangsgeld"]),
            fall("u07c-1", "Die vergessene Androhung",
                 "Die Lokalkammer verurteilt Kodak zur Unterlassung, ohne im Tenor ein Zwangsgeld anzudrohen. Nach Zustellung der Mitteilung nach R. 118.8 VerfO liefert Kodak weiter. Fujifilm beantragt bei der Lokalkammer, die Unterlassungsanordnung nachträglich mit der Androhung eines Zwangsgelds von 50.000 EUR je Verstoß zu versehen. Kodak meint, eine Ergänzung des Urteils sei nur im Wege der Berufung möglich; im Übrigen fehle einer nachträglichen Androhung die Grundlage.",
                 "Kann die Lokalkammer die Zwangsgeldandrohung nachträglich gesondert anordnen?", True,
                 ["**Ja!** Nach R. 354.3 VerfO **können** Entscheidungen und Anordnungen des Gerichts Zwangsgeldzahlungen für den Fall vorsehen, dass sich eine Partei nicht an die Anordnung „oder eine frühere Anordnung“ hält. Die Androhung muss deshalb nicht in der Hauptsacheentscheidung selbst stehen; sie kann später gesondert ergehen und an eine frühere Anordnung anknüpfen. Einer Berufung gegen die Hauptentscheidung bedarf es dafür nicht (EPG-BerG Kodak/Fujifilm).",
                  "Die Höhe legt das Gericht nach der Bedeutung der Anordnung fest (Art. 82 Abs. 4 EPGÜ, R. 354.3 VerfO): Das Zwangsgeld muss **abschreckend, aber verhältnismäßig** sein. Die Androhung muss bestimmen, bei welchem Ereignis welcher Betrag verfällt – als Pauschale oder je Zeitraum, Stück oder Handlung –, gegebenenfalls mit einem Höchstbetrag, der bei fortgesetzten Verstößen später erhöht werden kann. Fujifilms Antrag auf 50.000 EUR je Verstoß ist ein solcher bestimmter Maßstab; das Gericht prüft nur noch, ob der Betrag der Bedeutung der Anordnung entspricht."],
                 merke="R. 354.3: Zwangsgeld kann im Urteil oder nachträglich angedroht werden – bestimmt nach Ereignis und Betrag, abschreckend, verhältnismäßig.",
                 level=2, concepts=["upc_zwangsgeld", "upc_vollstreckung"], norms=["R. 354.3 VerfO", "Art. 82 Abs. 4 EPGÜ", "Art. 63 Abs. 2 EPGÜ"],
                 cases=["upc_coa_kodak_fujifilm_zwangsgeld"], step="step:upc_schema_verletzungsklage.3.4"),
            fall("u07c-2", "Geoblocking auf dem Marktplatz",
                 "Lepu ist unter Androhung eines Zwangsgelds verboten, Herzokkluder in Deutschland, Frankreich und den Niederlanden anzubieten und in Verkehr zu bringen. Lepu vertreibt über eine Online-Verkaufsplattform, der sie Produktbeschreibungen, Bilder und Preise liefert. Nach der Anordnung lässt Lepu die **Kaufoption** für Besucher aus den drei Ländern per Geoblocking sperren; die Produktseiten mit Beschreibung und Preis bleiben dort abrufbar. Occlutech beantragt die Festsetzung des Zwangsgelds. Lepu wendet ein, für den Plattforminhalt sei der Betreiber verantwortlich, und ohne Kaufmöglichkeit fehle es an einem Angebot.",
                 "Hat Lepu die Unterlassungsanordnung befolgt?", False,
                 ["**Nein!** Der Adressat einer Unterlassungsanordnung muss **Dritte kontrollieren**, denen er Aufgaben zur Umsetzung der Anordnung überträgt. Nutzt er eine Verkaufsplattform und liefert er selbst die Inhalte, muss er sicherstellen, dass diese Inhalte nicht gegen die Anordnung verstoßen; die Verantwortung lässt sich nicht auf den Plattformbetreiber abwälzen (EPG-BerG Lepu/Occlutech).",
                  "Das Geoblocking der Kaufoption genügt nicht, weil **Anbieten** und **Inverkehrbringen** nach Art. 25 lit. a EPGÜ selbständige Benutzungshandlungen sind, die beide verboten wurden. Anbieten ist wirtschaftlich zu verstehen: Es genügt die Präsentation, die Betrachtern ein Angebot auf Überlassung ermöglicht; Preisangabe und Lieferbereitschaft sind nicht erforderlich (EPG-BerG Belkin/Philips). Die abrufbare Produktseite bleibt ein Angebot für die verbotenen Gebiete. Ausreichen kann dagegen ein zutreffender **Website-Disclaimer**, wenn kein Besucher den Inhalt vernünftigerweise als Angebot für die verbotenen Gebiete verstehen kann. Das Zwangsgeld wird nach R. 354.4 VerfO festgesetzt."],
                 merke="Wer Inhalte an eine Plattform liefert, haftet für sie; Kaufknopf sperren reicht nicht, weil schon das Anbieten verboten ist.",
                 level=3, concepts=["upc_vollstreckung", "upc_anbieten", "upc_unterlassungsanordnung"], norms=["R. 354.4 VerfO", "Art. 25 EPGÜ", "Art. 63 EPGÜ"],
                 cases=["upc_coa_lepu_occlutech_vollstreckung", "upc_coa_belkin_philips_anbieten"], step="step:upc_schema_verletzungsklage.3.4"),
            fall("u07c-3", "Berufung gegen das festgesetzte Zwangsgeld",
                 "Die Lokalkammer setzt gegen EOFlow wegen fortgesetzter Lieferungen ein Zwangsgeld von 200.000 EUR fest (R. 354.4 VerfO) und lässt die Berufung nicht zu. EOFlow legt binnen 15 Tagen Berufung ein und beruft sich auf Art. 73 Abs. 2 lit. a EPGÜ: Die Festsetzung sei eine Anordnung im Zusammenhang mit der einstweiligen Maßnahme nach Art. 62 EPGÜ, die frei anfechtbar sei.",
                 "Ist die Berufung ohne Zulassung statthaft?", False,
                 ["**Nein!** Art. 73 Abs. 2 lit. a EPGÜ und R. 220.1 lit. c VerfO eröffnen die zulassungsfreie Berufung nur gegen Anordnungen nach Art. 49 Abs. 5, 59 bis 62 und 67 EPGÜ. Eine Anordnung zur **Festsetzung eines Zwangsgelds** nach Art. 82 Abs. 4 EPGÜ, R. 354.4 VerfO ist keine dieser Anordnungen, auch wenn sie eine einstweilige Maßnahme vollstreckt; sie ist eine Vollstreckungsentscheidung mit eigener Rechtsgrundlage (EPG-BerG EOFlow/Insulet). R. 354.4 Satz 5 VerfO sagt es ausdrücklich: Die Festsetzung „unterliegt der Berufung nach Regel 220.2“.",
                  "EOFlow kann daher nur den Weg der R. 220.2 bis 220.4 VerfO gehen: Berufung mit Zulassung durch das Gericht erster Instanz oder, wenn diese binnen 15 Tagen verweigert wird, Antrag auf **Ermessensüberprüfung** (discretionary review) an das Berufungsgericht binnen weiterer 15 Kalendertage; der ständige Richter entscheidet über die Zulassung (R. 220.4 VerfO). Die eingelegte Berufung ist unzulässig; ob sie in einen Antrag auf Ermessensüberprüfung umgedeutet werden kann, entscheidet das Berufungsgericht nach den Umständen."],
                 merke="Zwangsgeldfestsetzung = Anordnung nach R. 220.2: Berufung nur mit Zulassung oder nach Ermessensüberprüfung.",
                 level=3, concepts=["upc_zwangsgeld", "upc_ermessensueberpruefung", "upc_berufung"], norms=["R. 354.4 VerfO", "Art. 73 Abs. 2 EPGÜ", "R. 220.2 VerfO", "R. 220.4 VerfO"],
                 cases=["upc_coa_eoflow_insulet_zwangsgeld_berufung"], step="step:upc_schema_verletzungsklage.3.4"),
            fall("u07c-4", "Die aufgehobene Anordnung und die verfallenen Zwangsgelder",
                 "Die Lokalkammer hat Kodak zur Unterlassung verurteilt und später wegen dreier Verstöße Zwangsgelder von insgesamt 300.000 EUR festgesetzt. Auf die Berufung von Kodak hebt das Berufungsgericht die Unterlassungsanordnung auf, weil das Patent nicht verletzt ist. Fujifilm meint, die Zwangsgelder für die Verstöße **vor** der Aufhebung blieben bestehen: Bis dahin sei die Anordnung wirksam und vollstreckbar gewesen, und Kodak habe sie bewusst missachtet.",
                 "Bleiben die vor der Aufhebung festgesetzten Zwangsgelder bestehen?", False,
                 ["**Nein!** Hebt das Berufungsgericht die erstinstanzliche Entscheidung nach Art. 75 Abs. 1 EPGÜ, R. 242.1 VerfO auf, wirkt das in der Regel **zurück**: Die Unterlassungsanordnung gilt als nie wirksam gewesen. Damit verlieren auch Zwangsgeldfestsetzungen für Verstöße vor der Aufhebung ihre Grundlage (EPG-BerG Kodak/Fujifilm 2026). Das Zwangsgeld ist ein Beugemittel zur Durchsetzung der Anordnung, keine Strafe für Ungehorsam als solchen; fällt die Anordnung rückwirkend weg, gibt es nichts mehr durchzusetzen.",
                  "Folgerichtig können auch **Vollstreckungskosten** nicht auf Grundlage einer als nie wirksam geltenden Entscheidung zugewiesen werden. Umgekehrt kann Kodak nach R. 354.2 VerfO angemessenen Ersatz des durch die Vollstreckung verursachten Schadens verlangen (entsprechend § 717 Abs. 2 ZPO im deutschen Recht). Für die Berufung gegen die Zwangsgeldfestsetzung bemisst sich der Streitwert nach R. 370.6 VerfO nach dem Interesse der Partei, die das Vollstreckungsverfahren eingeleitet hat, nicht nach der Summe der verfallenen Zwangsgelder, denn diese fließen an das Gericht."],
                 merke="Aufhebung wirkt zurück: Mit der Anordnung fallen die Zwangsgelder – auch für Verstöße davor.",
                 level=3, concepts=["upc_vollstreckung", "upc_zwangsgeld", "upc_streitwert"], norms=["Art. 75 Abs. 1 EPGÜ", "R. 242.1 VerfO", "R. 354.2 VerfO", "R. 370.6 VerfO"],
                 cases=["upc_coa_kodak_fujifilm_aufhebung_zwangsgeld"], step="step:upc_schema_verletzungsklage.3.4"),
        ]),
    ],
)
